<script>
document.addEventListener('DOMContentLoaded',function(){
 var q=function(s){return document.querySelector(s)},qa=function(s){return Array.prototype.slice.call(document.querySelectorAll(s))},pick=function(n){return q('[name="'+n+'"]')},refresh=function(e){if(window.jQuery&&e)try{jQuery(e).selectpicker('refresh')}catch(x){}};
 var pm=pick('pricing_method'),sqm=q('.psp-sqm-price'),fix=q('.psp-fixed-price'),sqmIn=pick('price_per_sqm'),fixIn=pick('fixed_price');function pricingToggle(){var f=pm&&pm.value==='fixed';if(sqm)sqm.style.display=f?'none':'';if(fix)fix.style.display=f?'':'none';if(sqmIn)sqmIn.required=!f;if(fixIn)fixIn.required=f}if(pm){pm.addEventListener('change',pricingToggle);pricingToggle()}
 var sale=pick('sale_type_key'),saleName=q('#psp_sale_type_name');function syncSale(){if(saleName&&sale)saleName.value=sale.selectedIndex>=0?sale.options[sale.selectedIndex].text:''}if(sale)sale.addEventListener('change',syncSale);syncSale();
 var form=q('#psp-rule-form'),rid=q('#psp_rule_id'),notice=q('#psp-edit-notice'),submit=q('#psp-submit-btn'),active=pick('active');function setv(n,v){var e=pick(n);if(e){e.value=v||'';refresh(e)}}
 function resetEdit(){form.reset();rid.value='';notice.style.display='none';submit.textContent='<?php echo addslashes(_l('psp_save')); ?>';['group_id','sale_type_key','reeds','density','weave_type','design','commodity_code','size','pricing_method'].forEach(function(n){refresh(pick(n))});pricingToggle();syncSale()}q('#psp-cancel-edit').addEventListener('click',resetEdit);
 qa('.psp-edit-btn').forEach(function(b){b.addEventListener('click',function(){rid.value=this.dataset.id||'';setv('group_id',this.dataset.group);setv('sale_type_key',this.dataset.type);saleName.value=this.dataset.typeName||'';setv('reeds',this.dataset.reeds);setv('density',this.dataset.density);setv('weave_type',this.dataset.weave);setv('design',this.dataset.design);setv('commodity_code',this.dataset.code);setv('size',this.dataset.size);setv('pricing_method',this.dataset.method);sqmIn.value=this.dataset.sqm||'';fixIn.value=this.dataset.fixed||'';pick('valid_from').value=this.dataset.from||'';pick('valid_to').value=this.dataset.to||'';active.checked=this.dataset.active==='1';pricingToggle();notice.style.display='block';submit.innerHTML='<i class="fa fa-save"></i> ذخیره تغییرات';form.scrollIntoView({behavior:'smooth',block:'start'})})});
 function filter(){var text=(q('#psp-filter-text').value||'').trim().toLowerCase(),r=q('#psp-filter-reeds').value,d=q('#psp-filter-density').value,w=q('#psp-filter-weave').value,a=q('#psp-filter-active').value;qa('.psp-rule-row').forEach(function(x){var ok=(!text||(x.dataset.search||'').indexOf(text)>=0)&&(!r||x.dataset.reeds===r)&&(!d||x.dataset.density===d)&&(!w||x.dataset.weave===w)&&(a===''||x.dataset.active===a);x.style.display=ok?'':'none'})}['#psp-filter-text','#psp-filter-reeds','#psp-filter-density','#psp-filter-weave','#psp-filter-active'].forEach(function(s){var e=q(s);e.addEventListener(e.tagName==='INPUT'?'input':'change',filter)});q('#psp-filter-clear').addEventListener('click',function(){q('#psp-filter-text').value='';['#psp-filter-reeds','#psp-filter-density','#psp-filter-weave','#psp-filter-active'].forEach(function(s){q(s).value='';refresh(q(s))});filter()});
 function esc(v){var d=document.createElement('div');d.textContent=String(v==null?'':v);return d.innerHTML}qa('.psp-history-btn').forEach(function(b){b.addEventListener('click',function(){var u='<?php echo admin_url('product_sqm_pricing/history'); ?>?group_id='+encodeURIComponent(this.dataset.group)+'&sale_type_key='+encodeURIComponent(this.dataset.type)+'&reeds='+encodeURIComponent(this.dataset.reeds||'')+'&density='+encodeURIComponent(this.dataset.density||'')+'&weave_type='+encodeURIComponent(this.dataset.weave||'')+'&design='+encodeURIComponent(this.dataset.design||'')+'&commodity_code='+encodeURIComponent(this.dataset.code||'')+'&size='+encodeURIComponent(this.dataset.size||'');var body=q('#pspHistoryBody');body.innerHTML='<tr><td colspan="5" class="text-center"><i class="fa fa-spinner fa-spin"></i></td></tr>';$('#pspHistoryModal').modal('show');fetch(u,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).then(function(r){return r.json()}).then(function(j){if(!j.success)throw new Error(j.message||'خطا');q('#pspHistorySummary').textContent=(j.group_name||'')+' — '+(j.sale_type_name||'');body.innerHTML='';(j.rows||[]).forEach(function(x){var pv=x.pricing_method==='fixed'?Number(x.fixed_price):Number(x.price_per_sqm);body.innerHTML+='<tr><td>'+esc(x.display_from)+'</td><td>'+esc(x.display_to)+'</td><td>'+(x.pricing_method==='fixed'?'ثابت':'متری')+'</td><td>'+pv.toLocaleString('en-US')+'</td><td>'+(Number(x.active)?'فعال':'غیرفعال')+'</td></tr>'});if(!(j.rows||[]).length)body.innerHTML='<tr><td colspan="5" class="text-center text-muted">سابقه‌ای وجود ندارد.</td></tr>'}).catch(function(e){body.innerHTML='<tr><td colspan="5" class="text-danger">'+esc(e.message)+'</td></tr>'})})});
});
</script><?php init_tail(); ?>
